resource "aws_iam_user" "admin" {
  name          = "admin_${var.cgid}"
  force_destroy = true
}

resource "aws_iam_access_key" "admin_one" {
  user   = aws_iam_user.admin.name
  status = "Inactive"
}

resource "aws_iam_access_key" "admin_two" {
  user   = aws_iam_user.admin.name
  status = "Inactive"
}

resource "aws_iam_user_policy_attachment" "admin_iam_read" {
  user       = aws_iam_user.admin.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_user_policy" "admin_assume_role" {
  name = "AssumeRoles"
  user = aws_iam_user.admin.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AssumeRole"
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.secretsmanager_role.arn
      }
    ]
  })
}


resource "aws_iam_role" "secretsmanager_role" {
  name                  = "cg_secretsmanager_${var.cgid}"
  description           = "Access to view secrets"
  force_detach_policies = true

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.account_id
        }
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = true
          }
        }
      }
    ]
  })

  managed_policy_arns = [
    aws_iam_policy.role_read_secrets.arn
  ]
}

resource "aws_iam_policy" "role_read_secrets" {
  name        = "cg_view_secrets_${var.cgid}"
  description = "View and retreive secrets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "secretsmanager:ListSecrets"
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action   = "secretsmanager:GetSecretValue"
        Effect   = "Allow"
        Resource = aws_secretsmanager_secret.primary_secret.arn
      }
    ]
  })
}

# Developer IAM User
# The user it not needed for scenario completion
resource "aws_iam_user" "developer" {
  name          = "developer_${var.cgid}"
  force_destroy = true

  tags = {
    developer = "true"
  }
}

resource "aws_iam_access_key" "developer" {
  user = aws_iam_user.developer.name
}

resource "aws_iam_user_policy" "developer_manage_view_secrets" {
  name = "DeveloperViewSecrets"
  user = aws_iam_user.developer.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ViewSecrets"
        Effect   = "Allow"
        Action   = "secretsmanager:ListSecrets"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user" "manager" {
  name          = "manager_${var.cgid}"
  force_destroy = true
}

resource "aws_iam_access_key" "manager" {
  user = aws_iam_user.manager.name
}

resource "aws_iam_user_policy_attachment" "manager_iam_read" {
  user       = aws_iam_user.manager.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_user_policy" "manager_manage_access_keys" {
  name = "SelfManageAccess"
  user = aws_iam_user.manager.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SelfManageAccess"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice",
          "iam:GetMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:DeleteAccessKey",
          "iam:UpdateAccessKey",
          "iam:CreateAccessKey"
        ]
        Resource = [
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/*",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/*"
        ]
        Condition = {
          StringEquals = {
            "aws:ResourceTag/developer" = "true"
          }
        }
      },
      {
        Sid    = "CreateMFA"
        Effect = "Allow"
        Action = [
          "iam:DeleteVirtualMFADevice",
          "iam:CreateVirtualMFADevice"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/*"
      }
    ]
  })
}

resource "aws_iam_user_policy" "manager_tag_resources" {
  name = "TagResources"
  user = aws_iam_user.manager.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "TagResources"
        Effect = "Allow"
        Action = [
          "iam:UntagUser",
          "iam:UntagRole",
          "iam:TagRole",
          "iam:UntagMFADevice",
          "iam:UntagPolicy",
          "iam:TagMFADevice",
          "iam:TagPolicy",
          "iam:TagUser"
        ]
        Resource = "*"
      }
    ]
  })
}

output "manager_access_key_id" {
  description = "Manager Access Key ID"
  value       = aws_iam_access_key.manager.id
}

output "manager_secret_access_key" {
  description = "Manager Secret Access Key"
  value       = aws_iam_access_key.manager.secret
  sensitive   = true

}

output "aws_account_id" {
  description = "AWS Account ID"
  value       = data.aws_caller_identity.current.account_id
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

# Secret that is the flag for the scenario
resource "aws_secretsmanager_secret" "primary_secret" {
  name                    = "cg_secret_${var.cgid}"
  description             = "The primary secret for the ${var.scenario-name} scenario"
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "primary_secret_string" {
  secret_id     = aws_secretsmanager_secret.primary_secret.id
  secret_string = "flag{14m_PERM15510N5_4Re_5C4R_${sha256(formatdate("DD-MM-YYYY", timestamp()))}}"
}

variable "profile" {
  description = "The AWS profile to use"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming"
  type        = string
}

variable "region" {
  description = "The AWS region to deploy to"
  default     = "us-east-1"
  type        = string
}

variable "stack-name" {
  description = "Name of the CloudGoat stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario"
  default     = "iam_privesc_by_key_rotation"
  type        = string
}
